create or replace function public.deactivate_developer_client_account_rc1(p_client_id uuid,p_confirmation text) returns jsonb language plpgsql security definer set search_path=public set row_security=off as $$ declare v_user_id uuid; v_active_count integer; begin if auth.uid() is null or public.current_role()<>'platform_admin'::public.app_role then raise exception 'PLATFORM_ADMIN_REQUIRED' using errcode='42501'; end if; if p_confirmation<>'DEACTIVATE' then raise exception 'Type DEACTIVATE to confirm.'; end if; select user_id into v_user_id from public.clients where id=p_client_id; if v_user_id is null then raise exception 'Client workspace unavailable.'; end if; select count(*) into v_active_count from public.marketplace_jobs where client_id=p_client_id and status in('open','accepted','assigned','active'); if v_active_count>0 then raise exception 'Complete or cancel active security requests before deactivating this client account.'; end if; update public.profiles set account_status='disabled',updated_at=now() where id=v_user_id and role='client'; if not found then raise exception 'Client profile unavailable.'; end if; return jsonb_build_object('deactivated',true,'client_id',p_client_id); end; $$;
revoke all on function public.deactivate_developer_client_account_rc1(uuid,text) from public,anon;
grant execute on function public.deactivate_developer_client_account_rc1(uuid,text) to authenticated,service_role;
